commits.content:
*{
    margin:0;
    padding:0;
    box-sizing:border-box;
}

.login-container{

    display:flex;
    height:100vh;

    font-family:Arial, Helvetica, sans-serif;

}

.login-left{

    flex:1;

    background:linear-gradient(135deg,#0d6efd,#1e88e5);

    color:white;

    display:flex;

    justify-content:center;

    align-items:center;

    padding:60px;

}

.overlay{

    max-width:450px;

}

.overlay h1{

    font-size:48px;

    font-weight:bold;

}

.overlay p{

    margin-top:20px;

    font-size:20px;

    line-height:30px;

}

.features{

    margin-top:40px;

}

.features div{

    margin:15px 0;

    font-size:18px;

}

.login-right{

    flex:1;

    display:flex;

    justify-content:center;

    align-items:center;

    background:#f8f9fa;

}

.login-card{

    width:430px;

    background:white;

    padding:40px;

    border-radius:15px;

    box-shadow:0 10px 30px rgba(0,0,0,.15);

}

.login-card h2{

    color:#0d6efd;

    font-weight:bold;

}

.login-card p{

    color:gray;

    margin-bottom:30px;

}

.form-group{

    display:flex;

    flex-direction:column;

}

.form-group label{

    margin-bottom:8px;

    font-weight:600;

}

.form-control{

    height:50px;

}

.options{

    display:flex;

    justify-content:space-between;

    align-items:center;

    font-size:15px;

}

.options a{

    text-decoration:none;

}

.btn{

    height:50px;

    font-size:18px;

}

.register{

    text-align:center;

    margin-top:25px;

}

.register a{

    text-decoration:none;

    font-weight:bold;

}

@media(max-width:900px){

.login-left{

display:none;

}

.login-right{

width:100%;

}

.login-card{

width:90%;

}

}
